from build123d import *
import math

def hypocycloid(t, r1, r2):
    return (
        (r1 - r2) * math.cos(t) + r2 * math.cos(r1 / r2 * t - t),
        (r1 - r2) * math.sin(t) + r2 * math.sin(-(r1 / r2 * t - t))
    )

def epicycloid(t, r1, r2):
    return (
        (r1 + r2) * math.cos(t) - r2 * math.cos(r1 / r2 * t + t),
        (r1 + r2) * math.sin(t) - r2 * math.sin(r1 / r2 * t + t)
    )

def gear_point(t, r1=30, r2=5):
    if (-1) ** (1 + math.floor(t / (2 * math.pi) * (r1 / r2))) < 0:
        return epicycloid(t, r1, r2)
    else:
        return hypocycloid(t, r1, r2)

gear_thickness = 6.0
fillet_radius = 1.9
hole_diameter = 21.1
num_samples = 200

points = [gear_point(i * 2 * math.pi / num_samples) for i in range(num_samples + 1)]

with BuildPart() as p:
    with BuildSketch() as s:
        with BuildLine() as bl:
            Spline(*points)
        make_face()
    extrude(amount=gear_thickness)

solid_body = p.part
solid_body = fillet(solid_body.edges(), fillet_radius)

hole_positions = [
    (0, 0),
    (gear_thickness * 2, 0),
    (-gear_thickness * 2, 0),
    (0, gear_thickness * 2),
    (0, -gear_thickness * 2),
]

for x, y in hole_positions:
    solid_body = solid_body - Pos(x, y, gear_thickness / 2) * Cylinder(hole_diameter / 2, gear_thickness * 2)

part = solid_body
part.name = "gear_plate"
export_step(part, "output.step")
